// smoke.spec.js — tool-specific checks for Remove Duplicate Lines and Sort.
// Fixture: tests/fixtures/maple-street-bakery.txt (fictional, generated by tests/fixtures/make-bakery-fixture.mjs).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const SAMPLE = fs.readFileSync(fixture('maple-street-bakery.txt'), 'utf8');
const outputLines = async (page) => (await page.locator('#output').inputValue()).split('\n').filter((l, i, a) => !(i === a.length - 1 && l === ''));

test.describe('Remove Duplicate Lines and Sort', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
  });

  test('pasting the 40-line sample shows fewer output lines and a removed count', async ({ page }) => {
    expect(SAMPLE.split('\n').length - 1).toBe(40);
    await page.fill('#input', SAMPLE);
    await expect(page.locator('#stat-in')).toHaveText('40');
    const out = Number(await page.locator('#stat-out').textContent());
    expect(out).toBeLessThan(40);
    expect(out).toBe(25);
    expect(Number(await page.locator('#stat-dupes').textContent())).toBeGreaterThan(0);
    await expect(page.locator('#stat-blank')).toHaveText('4');
    await expect(page.locator('#input-count')).toHaveText('40 lines');
    await expect(page.locator('#output-count')).toHaveText('25 lines');
    expect(await outputLines(page)).toHaveLength(25);
  });

  test('Load sample button fills the empty input', async ({ page }) => {
    await expect(page.locator('#load-sample')).toBeVisible();
    await page.click('#load-sample');
    await expect(page.locator('#input')).toHaveValue(SAMPLE);
    await expect(page.locator('#stat-out')).toHaveText('25');
    await expect(page.locator('#load-sample')).toBeHidden();
  });

  test('ignore case merges Apple and apple; turning it off keeps both', async ({ page }) => {
    await page.fill('#input', 'Apple\napple\nbanana\n');
    await expect(page.locator('#opt-case')).toBeChecked();
    await expect(page.locator('#stat-out')).toHaveText('2');
    expect(await outputLines(page)).toEqual(['Apple', 'banana']);
    await page.uncheck('#opt-case');
    await expect(page.locator('#stat-out')).toHaveText('3');
    expect(await outputLines(page)).toEqual(['Apple', 'apple', 'banana']);
    await page.check('#opt-case');
    await expect(page.locator('#stat-out')).toHaveText('2');
  });

  test('A to Z sorts alphabetically and natural sort puts item2 before item10', async ({ page }) => {
    await page.fill('#input', 'pear\nitem10\napple\nitem2\nBanana\ncrème\n');
    await page.selectOption('#opt-sort', 'az');
    await expect.poll(() => outputLines(page)).toEqual(['apple', 'Banana', 'crème', 'item10', 'item2', 'pear']);
    await page.selectOption('#opt-sort', 'natural');
    const nat = await outputLines(page);
    expect(nat.indexOf('item2')).toBeLessThan(nat.indexOf('item10'));
    expect(nat).toEqual(['apple', 'Banana', 'crème', 'item2', 'item10', 'pear']);
    await page.selectOption('#opt-sort', 'za');
    expect(await outputLines(page)).toEqual(['pear', 'item2', 'item10', 'crème', 'Banana', 'apple']);
  });

  test('removed-lines panel lists each dropped line with how often it appeared', async ({ page }) => {
    await page.fill('#input', SAMPLE);
    const panel = page.locator('#removed');
    await expect(panel).toBeVisible();
    await panel.locator('summary').click();
    const items = panel.locator('#removed-list li');
    await expect(items).toHaveCount(10);
    const flour = items.filter({ has: page.locator('code', { hasText: /^flour$/ }) });
    await expect(flour).toContainText('appeared 3 times');
    // Composed and decomposed crème fraîche (three spellings) are one key.
    await expect(items.filter({ hasText: 'crème fraîche' })).toContainText('appeared 3 times');
    await expect(items.filter({ hasText: '(blank line)' })).toContainText('appeared 4 times');
    await expect(page.locator('#removed-count')).toHaveText('15');
  });

  test('output can be copied (button and Ctrl+Enter) and downloaded as unique-lines.txt', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await page.fill('#input', SAMPLE);
    await expect(page.locator('#stat-out')).toHaveText('25');
    const expected = (await outputLines(page)).join('\n') + '\n';

    await page.click('#copy');
    await expect(page.locator('.toast')).toContainText('Copied 25 lines');
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(expected);

    await page.evaluate(() => navigator.clipboard.writeText(''));
    await page.locator('#input').focus();
    await page.keyboard.press('Control+Enter');
    await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe(expected);

    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('unique-lines.txt');
    const body = fs.readFileSync(await download.path(), 'utf8');
    expect(body).toBe(expected);
    expect(body.split('\n')).toHaveLength(26);
    expect(body).toContain('flour\n');
  });

  test('keep last, only duplicated and only unique modes', async ({ page }) => {
    await page.fill('#input', 'a\nb\nA\nc\n');
    await page.selectOption('#opt-mode', 'last');
    expect(await outputLines(page)).toEqual(['b', 'A', 'c']);
    await page.selectOption('#opt-mode', 'dupes');
    expect(await outputLines(page)).toEqual(['a']);
    await page.selectOption('#opt-mode', 'unique');
    expect(await outputLines(page)).toEqual(['b', 'c']);
  });

  test('trim, collapse and blank options change the result; trailing newline adds no phantom line', async ({ page }) => {
    await page.fill('#input', 'butter   \nbutter\nbaking  soda\nbaking soda\n\n');
    await expect(page.locator('#stat-in')).toHaveText('5');
    await expect(page.locator('#stat-out')).toHaveText('3');
    await page.check('#opt-collapse');
    await expect(page.locator('#stat-out')).toHaveText('2');
    await page.uncheck('#opt-trim');
    await expect(page.locator('#stat-out')).toHaveText('3');
    await page.uncheck('#opt-blank');
    await expect(page.locator('#stat-out')).toHaveText('4');
    await expect(page.locator('#stat-blank')).toHaveText('0');
  });

  test('CRLF input keeps CRLF in the download; swap moves output into input', async ({ page }) => {
    await page.fill('#input', 'x\r\ny\r\nx\r\n');
    await expect(page.locator('#stat-out')).toHaveText('2');
    await expect(page.locator('#summary')).toContainText('line endings CRLF');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(fs.readFileSync(await download.path(), 'utf8')).toBe('x\r\ny\r\n');
    await page.click('#swap');
    await expect(page.locator('#stat-in')).toHaveText('2');
    await expect(page.locator('#stat-dupes')).toHaveText('0');
  });

  test('loads a .txt file and rejects other file types with a clear error', async ({ page }) => {
    await page.setInputFiles('#file-input', [fixture('maple-street-bakery.txt'), fixture('sample.png')]);
    await expect(page.locator('#stat-in')).toHaveText('40');
    await expect(page.locator('#results .alert--error')).toContainText('sample.png was skipped');
    await page.setInputFiles('#file-input', fixture('sample.png'));
    await expect(page.locator('#results .alert--error')).toContainText('only .txt, .csv and .log');
  });

  test('invisible characters show an info hint', async ({ page }) => {
    await page.fill('#input', 'oat milk\noat\u00a0milk\n');
    await expect(page.locator('#results .alert--info')).toContainText('invisible characters');
    await expect(page.locator('#stat-out')).toHaveText('2');
    await page.check('#opt-collapse');
    await expect(page.locator('#stat-out')).toHaveText('1');
  });

  test('emoji lines are compared by code point and length sort counts them as one character', async ({ page }) => {
    await page.fill('#input', 'ab\n🍞\n🍞\nabc\n');
    await expect(page.locator('#stat-out')).toHaveText('3');
    await page.selectOption('#opt-sort', 'len-asc');
    expect(await outputLines(page)).toEqual(['🍞', 'ab', 'abc']);
  });

  test('large inputs run in a worker with a progress bar and preview note', async ({ page }) => {
    await page.evaluate(() => {
      const lines = [];
      for (let i = 0; i < 250000; i++) lines.push(`sku-${i % 120000}`);
      const ta = document.getElementById('input');
      ta.value = lines.join('\n');
      ta.dispatchEvent(new Event('input', { bubbles: true }));
    });
    await expect(page.locator('#stat-in')).toHaveText((250000).toLocaleString('en-US'), { timeout: 30_000 });
    await expect(page.locator('#stat-out')).toHaveText((120000).toLocaleString('en-US'));
    await expect(page.locator('#preview-note')).toContainText('first 5,000');
    await expect(page.locator('#progress')).toBeHidden();
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    const body = fs.readFileSync(await download.path(), 'utf8');
    expect(body.split('\n')).toHaveLength(120000);
  });

  test('works at 390px wide without horizontal scroll', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await page.click('#load-sample');
    await expect(page.locator('#stat-out')).toHaveText('25');
    await page.locator('#removed summary').click();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const inBox = await page.locator('#input').boundingBox();
    const outBox = await page.locator('#output').boundingBox();
    expect(outBox.y).toBeGreaterThan(inBox.y + inBox.height - 1); // panes stack vertically
    for (const id of ['#copy', '#download', '#swap', '#opt-mode', '#opt-sort']) {
      const b = await page.locator(id).boundingBox();
      expect(b.x).toBeGreaterThanOrEqual(0);
      expect(b.x + b.width).toBeLessThanOrEqual(391);
    }
  });

  test('__demo shows a finished result from the fixture', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#stat-out')).toHaveText('25');
    await expect(page.locator('#removed')).toHaveAttribute('open', '');
    const out = await outputLines(page);
    expect(out.indexOf('item2')).toBeLessThan(out.indexOf('item10'));
  });
});
